use vstd::prelude::*;

verus! {
    // Helper function to convert a character to lowercase if it's an uppercase ASCII letter
    spec fn to_lower(c: char) -> char {
        if c >= 'A' && c <= 'Z' {
            (c as u8 + 32) as char // Convert to lowercase
        } else {
            c // Return unchanged
        }
    }

    // Main function to check if the input vector forms a palindrome
    fn is_palindrome(text: Vec<char>) -> (result: bool)
        ensures
            result == (forall |i: nat| (i < text.len() as nat) ==> 
                to_lower(text[i]) == to_lower(text[(text.len() - 1 - i) as usize])),
    {
        let n = text.len();
        let mut i: nat = 0;

        // Loop to compare characters from the start and end
        while i < (n as nat) / 2
            invariant
                i <= (n as nat) / 2,
                forall |j: nat| (j < i) ==> 
                    to_lower(text[j]) == to_lower(text[(n - 1 - j) as usize]),
            decreases (n as nat) / 2 - i,
        {
            // Assert that the characters at the mirrored positions are equal
            assert(to_lower(text[i]) == to_lower(text[(n - 1 - i) as usize]));
            i = i + 1;
        }

        // If we complete the loop, it means all mirrored characters matched
        true
    }
}
